head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkbox > M > getDataListInfo]<br/>컴포넌트의 아이템이 정의된 DataCollection 의 정보를 반환합니다.",
    "validation" : [        
        "renderType=native 인 경우 null 값을 반환합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    scwin.comp_init();
};



// comp 재생성
scwin.comp_init = function () {

};



scwin.btn_getDataListInfo_onclick = function (e) {
    let rtn = '';

    rtn = target1.getDataListInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("getDataListInfo : " + rtn);    
    wf_body_bottom.getObj("scwin").setReturnValue("getDataListInfo.nodeset : " + rtn.nodeset);
    wf_body_bottom.getObj("scwin").setReturnValue("getDataListInfo.id : " + rtn.id);
    wf_body_bottom.getObj("scwin").setReturnValue("getDataListInfo.value : " + rtn.value);
    wf_body_bottom.getObj("scwin").setReturnValue("getDataListInfo.label : " + rtn.label);
};
